package ociresources

import (
	"slices"
	"testing"
)

func TestNextFilter(t *testing.T) {
	g := resultFilter{groupSlug: "prod"}
	a := resultFilter{entryKey: "a"}
	c := resultFilter{entryKey: "c"}
	stops := []resultFilter{g, a, c}
	tests := []struct {
		name  string
		stops []resultFilter
		cur   resultFilter
		want  resultFilter
	}{
		{"no stops, off", nil, resultFilter{}, resultFilter{}},
		{"no stops, a stale filter goes off", nil, a, resultFilter{}},
		{"off goes to the first stop", stops, resultFilter{}, g},
		{"a stop goes to the next", stops, g, a},
		{"the middle stop goes to the next", stops, a, c},
		{"the last stop goes back to off", stops, c, resultFilter{}},
		{"an unknown filter goes off", stops, resultFilter{entryKey: "zzz"}, resultFilter{}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := nextFilter(tt.stops, tt.cur); got != tt.want {
				t.Errorf("nextFilter = %+v, want %+v", got, tt.want)
			}
		})
	}
}

func TestFilterStopsFor(t *testing.T) {
	b := &RegistryBrowser{entries: []browserRegistryEntry{
		{key: "hub", Slug: "hub"},
		{key: "m1", Slug: "prod", ParentSlug: "prod"},
		{key: "m2", Slug: "prod", ParentSlug: "prod"},
		{key: "m3", Slug: "prod", ParentSlug: "prod"},
		{key: "solo", Slug: "solo"},
	}}
	g := resultFilter{groupSlug: "prod"}
	e := func(k string) resultFilter { return resultFilter{entryKey: k} }
	tests := []struct {
		name string
		keys []string
		want []resultFilter
	}{
		{"no key", nil, nil},
		{"one key", []string{"hub"}, nil},
		{"one key repeated", []string{"hub", "hub"}, nil},
		{"two lone registries", []string{"hub", "solo"}, []resultFilter{e("hub"), e("solo")}},
		{"a group and a foreign registry", []string{"m1", "m2", "hub"}, []resultFilter{g, e("m1"), e("m2"), e("hub")}},
		{"a group covering every member is dropped", []string{"m1", "m2", "m3"}, []resultFilter{e("m1"), e("m2"), e("m3")}},
		{"the order follows the keys", []string{"solo", "hub"}, []resultFilter{e("solo"), e("hub")}},
		{"duplicates collapse", []string{"hub", "solo", "hub", "solo"}, []resultFilter{e("hub"), e("solo")}},
		{"an unknown key is a registry", []string{"hub", "ghost"}, []resultFilter{e("hub"), e("ghost")}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := b.filterStopsFor(tt.keys); !slices.Equal(got, tt.want) {
				t.Errorf("filterStopsFor(%v) = %+v, want %+v", tt.keys, got, tt.want)
			}
		})
	}
}

entries.description:
Work items -- issues, tasks and epics.

Actions:
  list (no required params; optional project_id, pql, order_by, per_page, cursor, expand, fields, external_id, external_source) -- omit project_id to search the whole workspace;
  list_archived (project_id; optional pql, order_by, per_page, cursor, expand, fields, external_id, external_source);
  retrieve (project_id, workitem_id; optional expand, fields, external_id, external_source, order_by);
  retrieve_by_identifier (workitem_identifier; optional expand, fields, external_id, external_source, order_by) -- identifier is PROJECT-N, e.g. ENG-42;
  search (query; optional expand, fields, external_id, external_source, order_by);
  count (no required params; optional project_id, pql, group_by, sub_group_by) -- counts the whole workspace unless project_id narrows it;
  create (project_id, name; optional assignees, labels, type_id, point, description_html, description_stripped, priority, start_date, target_date, sort_order, is_draft, parent, state, estimate_point, external_source, external_id);
  update (project_id, workitem_id; optional name, assignees, labels, type_id, point, description_html, description_stripped, priority, start_date, target_date, sort_order, is_draft, parent, state, estimate_point, external_source, external_id) -- only the fields you pass are changed;
  delete (project_id, workitem_id);
  archive (project_id, workitem_id; optional archive) -- archive defaults to true; pass archive=false to unarchive. Only completed or cancelled items can be archived;
  manage_assignee (project_id, workitem_id; optional add_user_id, remove_user_id) -- each takes one id or several; the list is merged, not replaced, and removals apply first;
  manage_label (project_id, workitem_id; optional add_label_id, remove_label_id) -- each takes one id or several; the list is merged, not replaced, and removals apply first.

priority: urgent, high, medium, low, none.
UUID fields (assignees, labels, state, parent, type_id) need UUIDs -- list the relevant resource first if you only have a name.
description_stripped is plain text and is wrapped into HTML on save; description_html wins if both are given.
To clear a field on update: assignees=[] or labels=[], and start_date=null or target_date=null. A field you leave out is not changed.
fields is a sparse fieldset: use `project`, not project_id, and `description_html`, not description.
count group_by and sub_group_by accept: state_id, state__group, priority, project_id, type_id, labels__id, assignees__id, issue_module__module_id, release_work_items__release_id, cycle_id, milestone_id, created_by, target_date, start_date. These are grouping keys only -- they are not PQL filter fields, and filtering on state__group is rejected.

Comments on a work item.

Actions:
  list (project_id, workitem_id; optional cursor, per_page);
  retrieve (project_id, workitem_id, comment_id);
  create (project_id, workitem_id, comment_html; optional access, external_source, external_id);
  update (project_id, workitem_id, comment_id; optional comment_html, access, external_source, external_id);
  delete (project_id, workitem_id, comment_id).

comment_html is HTML, e.g. '<p>Looks good.</p>'. access is INTERNAL or EXTERNAL.
To mention someone, write @[<user uuid>] inline -- '<p>@[<user uuid>] can you review?</p>' -- and the chip and the notification are generated for you. A bare @name is ordinary text that notifies nobody. The id must belong to a member of the work item's project; `member list_project` resolves a name to one. Mentions read back in the same form.

